import { diagramContentNodes } from './diagramContentNodes';

export interface SubtreeRange { startLine: number; endLine: number }
export function diagramSubtreeRange(diagram: Diagram, contentNodeId: string): SubtreeRange {
  const nodes = diagramContentNodes(diagram.content), root = nodes.find(node => node.id === contentNodeId);
  if (!root) throw Error('STALE_SUBTREE: select a current node');
  const ids = new Set<string>();
  const visit = (id: string) => { if (ids.has(id)) return; ids.add(id); nodes.find(node => node.id === id)?.childIds.forEach(visit); };
  visit(root.id);
  const descendants = nodes.filter(node => ids.has(node.id));
  const last = Math.max(...descendants.map(node => node.line), ...root.foldRanges.map(range => range.endLine));
  if (nodes.some(node => node.line >= root.line && node.line <= last && !ids.has(node.id)))
    throw Error('This selection is not a contiguous subtree. Choose a tree branch.');
  return { startLine: root.line, endLine: last };
}

/** A candidate contains full context, but only the selected range may differ. */
export function subtreeReplacement(base: Diagram, ascii: string, range: SubtreeRange): string {
  const before = base.content.ascii.split('\n'), after = ascii.split('\n');
  const prefix = before.slice(0, range.startLine - 1), suffix = before.slice(range.endLine);
  if (after.length < prefix.length + suffix.length || prefix.some((line, i) => line !== after[i])
    || suffix.some((line, i) => line !== after[after.length - suffix.length + i]))
    throw Error('SUBTREE_SCOPE: preserve every line outside the selected subtree exactly');
  return after.slice(prefix.length, after.length - suffix.length).join('\n');
}

export type ReplaceMode = 'diagram' | 'subnode-single' | 'multi-contiguous' | 'multi-disjoint';
export interface SubtreeTarget { contentNodeId: string; revisionId: string }
/** Resolve revision-pinned subtree roots before invoking the model. Never widen a selection. */
export function diagramReplacementRanges(diagram: Diagram, mode: ReplaceMode, subtree?: SubtreeTarget, subtrees?: SubtreeTarget[]): SubtreeRange[] {
  if (mode === 'diagram') {
    if (subtree || subtrees) throw Error('REPLACEMENT_SCOPE: diagram mode cannot include subtree targets');
    return [];
  }
  const targets = mode === 'subnode-single' ? subtree && !subtrees ? [subtree] : [] : !subtree ? subtrees ?? [] : [];
  if (targets.length < (mode === 'subnode-single' ? 1 : 2)) throw Error('REPLACEMENT_SCOPE: supply subtree for subnode-single, or at least two subtrees for a multi mode');
  if (targets.some(target => target.revisionId !== diagram.content.revisionId)) throw Error('VERSION_CONFLICT: selected subtree changed; select it again');
  const ranges = targets.map(target => ({ ...diagramSubtreeRange(diagram, target.contentNodeId), id: target.contentNodeId })).sort((a, b) => a.startLine - b.startLine);
  if (ranges.some((range, i) => i > 0 && range.startLine <= ranges[i - 1].endLine)) throw Error('REPLACEMENT_SCOPE: subtree targets must not overlap or repeat');
  if (mode === 'multi-contiguous') {
    if (ranges.some((range, i) => i > 0 && diagram.content.ascii.split('\n').slice(ranges[i - 1].endLine, range.startLine - 1).some(line => line.trim())))
      throw Error('REPLACEMENT_SCOPE: multi-contiguous requires adjacent subtrees');
    return [{ startLine: ranges[0].startLine, endLine: ranges.at(-1)!.endLine }];
  }
  if (mode === 'multi-disjoint' && ranges.some((range, i) => i > 0 && range.startLine === ranges[i - 1].endLine + 1))
    throw Error('REPLACEMENT_SCOPE: adjacent subtrees use multi-contiguous');
  return ranges.map(({ startLine, endLine }) => ({ startLine, endLine }));
}

/** Output line ranges correspond, in order, to the requested input ranges. Empty output uses endLine = startLine - 1. */
export function scopedReplacements(base: Diagram, ascii: string, ranges: readonly SubtreeRange[], outputRanges?: readonly SubtreeRange[]) {
  const before = base.content.ascii.split('\n'), after = ascii.split('\n');
  if (!ranges.length) throw Error('REPLACEMENT_SCOPE: expected at least one range');
  if (ranges.length === 1 && !outputRanges) {
    const range = ranges[0];
    subtreeReplacement(base, ascii, range);
    outputRanges = [{ startLine: range.startLine, endLine: after.length - (before.length - range.endLine) }];
  }
  if (!outputRanges || outputRanges.length !== ranges.length) throw Error('REPLACEMENT_SCOPE: supply one output range for every selected range');
  let oldEnd = 0, newEnd = 0;
  const patches = ranges.map((range, i) => {
    const output = outputRanges![i];
    for (const [r, length, end] of [[range, before.length, oldEnd], [output, after.length, newEnd]] as const) {
      if (!Number.isInteger(r.startLine) || !Number.isInteger(r.endLine) || r.startLine <= end || r.startLine > length + 1 || r.endLine < r.startLine - 1 || r.endLine > length)
        throw Error('REPLACEMENT_SCOPE: invalid or overlapping line ranges');
    }
    const gap = before.slice(oldEnd, range.startLine - 1), nextGap = after.slice(newEnd, output.startLine - 1);
    if (gap.length !== nextGap.length || gap.some((line, j) => line !== nextGap[j])) throw Error('REPLACEMENT_SCOPE: preserve every line outside the selected ranges exactly');
    oldEnd = range.endLine; newEnd = output.endLine;
    return { start: range.startLine, end: range.endLine, patch: after.slice(output.startLine - 1, output.endLine) };
  });
  const tail = before.slice(oldEnd), nextTail = after.slice(newEnd);
  if (tail.length !== nextTail.length || tail.some((line, i) => line !== nextTail[i])) throw Error('REPLACEMENT_SCOPE: preserve every line outside the selected ranges exactly');
  return { patches, outputRanges: [...outputRanges] };
}
"},{"path":"domain/core/diagrams/diagramConnection.ts","text":"import { z } from 'zod';
import type { GridBox, LineGridScene } from './lineGrid';
import { diagramContentNodes as connectionContentNodes } from './diagramContentNodes';
export { diagramContentNodes as connectionContentNodes } from './diagramContentNodes';

const id = z.string().min(1).max(500).refine(value => !['__proto__', 'constructor', 'prototype'].includes(value));
const offset = z.number().min(0).max(1).optional();
const side = z.enum(['auto', 'horizontal', 'left', 'right', 'top', 'bottom']).default('auto');
export const contentNodeAnchorSchema = z.object({
  kind: z.literal('content-node'), displayNodeId: id, contentNodeId: id, revisionId: id, side, offset
}).strict();
export const boxAnchorSchema = z.object({ kind: z.literal('box'), displayNodeId: id, side, offset }).strict();
export const anchorSchema = z.discriminatedUnion('kind', [contentNodeAnchorSchema, boxAnchorSchema]);
export const arrowLabelSchema = z.object({
  text: z.string().max(120),
  /** Absolute canvas pixels: horizontal center and text baseline, before pan/zoom. */
  position: z.object({ x: z.number().finite(), y: z.number().finite() }).strict().optional()
}).strict();
export const arrowAppearanceSchema = z.object({
  color: z.string().regex(/^#[0-9a-fA-F]{6}$/).default('#88c0d0'),
  lineStyle: z.enum(['solid', 'dashed']).default('solid'),
  label: z.union([z.string().max(120), arrowLabelSchema]).default('')
}).strict();
export const diagramConnectionSchema = z.object({
  id, source: contentNodeAnchorSchema, target: anchorSchema,
  appearance: arrowAppearanceSchema
}).strict();
export type ContentNodeAnchor = z.infer<typeof contentNodeAnchorSchema>;
export type GridBoxAnchor = z.infer<typeof boxAnchorSchema>;
export type DiagramAnchor = ContentNodeAnchor | GridBoxAnchor;
export type DiagramConnection = z.infer<typeof diagramConnectionSchema>;
export type ArrowAppearance = DiagramConnection['appearance'];
export type ArrowLabel = z.infer<typeof arrowLabelSchema>;
export const defaultArrowAppearance: ArrowAppearance = { color: '#88c0d0', lineStyle: 'solid', label: '' };

/** Legacy saved edges and callers may still supply a plain string. */
export function getArrowLabel(appearance: ArrowAppearance): ArrowLabel {
  return typeof appearance.label === 'string' ? { text: appearance.label } : appearance.label;
}

export function connectionBox(scene: LineGridScene, displayNodeId: string): GridBox | undefined {
  if (!displayNodeId.startsWith('grid:')) return undefined;
  const find = (box: GridBox): GridBox | undefined => box.id === displayNodeId.slice(5) ? box
    : box.kind === 'container' ? box.children.map(find).find(Boolean) : undefined;
  return find(scene.root);
}

export function validateConnectionAnchor(scene: LineGridScene, anchor: DiagramAnchor, allowStale = false) {
  const box = connectionBox(scene, anchor.displayNodeId);
  if (!box) throw new Error('Connection requires an existing GridBox');
  if (anchor.kind === 'box') return;
  if (box.kind !== 'diagram') throw new Error('Content anchor requires a diagram');
  const content = scene.contents[box.contentId].content;
  if (allowStale && content.revisionId !== anchor.revisionId) return;
  if (content.revisionId !== anchor.revisionId || !connectionContentNodes(content).some(node => node.id === anchor.contentNodeId)) {
    throw new Error('STALE_CONTENT_NODE: choose a current connection endpoint');
  }
}

export function validateConnections(scene: LineGridScene, input: unknown): DiagramConnection[] {
  const edges = z.array(diagramConnectionSchema).max(2000).parse(input ?? []);
  const seen = new Set<string>();
  for (const edge of edges) {
    if (seen.has(edge.id)) throw new Error('Duplicate connection ID');
    seen.add(edge.id);
    validateConnectionAnchor(scene, edge.source, true);
    validateConnectionAnchor(scene, edge.target, true);
  }
  return edges;
}

/** Deletions remove incident edges. Only proven node correspondence can rebase changed content. */
export function reconcileConnections(before: LineGridScene, after: LineGridScene, edges: readonly DiagramConnection[], nodeIds?: ReadonlyMap<string, string>): DiagramConnection[] {
  const update = <T extends DiagramAnchor>(anchor: T): T => {
    if (anchor.kind !== 'content-node') return anchor;
    const oldBox = connectionBox(before, anchor.displayNodeId), newBox = connectionBox(after, anchor.displayNodeId);
    if (oldBox?.kind !== 'diagram' || newBox?.kind !== 'diagram') return anchor;
    const oldContent = before.contents[oldBox.contentId].content, content = after.contents[newBox.contentId].content;
    if (oldContent.revisionId === content.revisionId || oldContent.revisionId !== anchor.revisionId) return anchor;
    const mapped = nodeIds?.get(anchor.contentNodeId);
    if (mapped && connectionContentNodes(content).some(node => node.id === mapped))
      return { ...anchor, revisionId: content.revisionId, contentNodeId: mapped };
    if (oldContent.ascii !== content.ascii || oldContent.structure.kind !== content.structure.kind) return anchor;
    const oldNode = connectionContentNodes(oldContent).find(node => node.id === anchor.contentNodeId);
    const node = oldNode && connectionContentNodes(content).find(node => node.line === oldNode.line && node.startColumn === oldNode.startColumn);
    return node ? { ...anchor, revisionId: content.revisionId, contentNodeId: node.id } : anchor;
  };
  return edges.filter(edge => connectionBox(after, edge.source.displayNodeId) && connectionBox(after, edge.target.displayNodeId))
    .map(edge => ({ ...edge, source: update(edge.source), target: update(edge.target) }));
}
